fn exercise(
    route: impl Fn(&CoreContext, &str, &str) -> Option<String>,
    icon: impl Fn(&CoreContext, &str) -> Option<String>,
    command_icon: impl Fn(&CoreContext, &str) -> Option<String>,
    validate: impl Fn(&Value) -> Result<(), String>,
    resolve: impl Fn(&CoreContext, &str) -> Result<PathBuf, String>,
    prefs: impl Fn(&CoreContext, &str) -> Option<PathBuf>,
    patched: bool,
) {
    let d = profile();
    let c = CoreContext {
        paths: Paths {
            data_dir: d.path().into(),
        },
    };
    let id = "com.tezbar.native.image-base64";
    let aliases = json!(["com.tezbar.image-base64", "raycast.image-base64"]);
    let dir = package(&c, id, "image-base64", aliases.clone());
    let base: Value = serde_json::from_str(include_str!("../extension.json")).unwrap();
    assert!(validate(&base).is_ok());
    for (key, value) in [
        ("schemaVersion", json!(2)),
        ("runtime", json!("javascript")),
        ("execution", json!("embedded")),
        ("protocolVersion", json!(2)),
        ("id", json!("com.tezbar.native.other")),
        ("capabilities", json!(["unknown"])),
        ("commands", json!([{"name":"../bad"}])),
    ] {
        let mut m = base.clone();
        m[key] = value;
        assert!(validate(&m).is_err(), "negative {key}");
    }
    assert_eq!(resolve(&c, id).unwrap(), dir);
    assert_eq!(route(&c, id, "base64-to-image"), Some(id.into()));
    assert_eq!(
        route(&c, "com.tezbar.image-base64", "base64-to-image").is_some(),
        patched
    );
    assert_eq!(
        route(&c, "raycast.image-base64", "image-to-base64"),
        Some(id.into())
    );
    assert!(route(&c, "com.tezbar.image-base64-other", "base64-to-image").is_none());
    assert!(route(&c, id, "unknown").is_none());
    assert_eq!(icon(&c, id).is_some(), patched);
    assert_eq!(command_icon(&c, id).is_some(), patched);
    if patched {
        assert_eq!(
            PathBuf::from(icon(&c, id).unwrap()),
            dir.join("resources/extension-icon.png")
        );
    }
    // Canonical preferences retain a different location from version resources.
    let canonical = dir.parent().unwrap().parent().unwrap();
    std::fs::write(canonical.join("preferences.json"), b"{}").unwrap();
    assert!(canonical.join("preferences.json").is_file());
    assert!(!dir.join("preferences.json").exists());
    assert_eq!(prefs(&c, id), Some(canonical.join("preferences.json")));
    // Duplicate aliases are rejected; same suffix without declaration never grants a route.
    let other = package(&c, "com.tezbar.native.other", "other", aliases);
    if patched {
        assert!(route(&c, "raycast.image-base64", "base64-to-image").is_none());
        assert!(route(&c, "com.tezbar.image-base64", "base64-to-image").is_none());
    }
    std::fs::remove_dir_all(other.parent().unwrap().parent().unwrap()).unwrap();
    std::fs::write(dir.join("extra"), b"uninventoried").unwrap();
    assert!(resolve(&c, id).is_err());
    std::fs::remove_file(dir.join("extra")).unwrap();
    std::fs::write(dir.join("bin/image-base64"), b"tampered").unwrap();
    assert!(resolve(&c, id).is_err());
    assert!(route(&c, id, "base64-to-image").is_none());
    if patched {
        assert!(icon(&c, id).is_none());
    }
}
